@page "/"

<PageTitle>RecipeShare - Home</PageTitle>

<h1>Welcome to RecipeShare</h1>
<p class="lead">Discover and share delicious recipes from our community.</p>

<h2>Browse by Category</h2>
<div class="row">
    @foreach (var category in Categories)
    {
        <div class="col-md-4 mb-4">
            <div class="card h-100">
                <div class="card-body">
                    <h5 class="card-title">@category.Name</h5>
                    <p class="card-text">@category.Description</p>
                    <a href="@($"category/{category.Slug}")" class="btn btn-primary">Browse Recipes</a>
                </div>
            </div>
        </div>
    }
</div>

@code {
    private static readonly List<CategoryInfo> Categories =
    [
        new("Breakfast", "breakfast", "Start your day right with pancakes, eggs, smoothies, and more."),
        new("Main Courses", "main-courses", "Hearty dinners and lunches for the whole family."),
        new("Desserts", "desserts", "Sweet treats including cakes, cookies, and pastries."),
        new("Appetizers", "appetizers", "Starters and snacks perfect for parties and gatherings."),
        new("Soups & Salads", "soups-salads", "Light and refreshing options for any season."),
        new("Vegetarian", "vegetarian", "Delicious meat-free meals packed with flavor.")
    ];

    private record CategoryInfo(string Name, string Slug, string Description);
}

