@page "/category/{Slug}"

<PageTitle>@GetCategoryName() - RecipeShare</PageTitle>

<h1>@GetCategoryName()</h1>
<p><a href="/">← Back to Categories</a></p>

@if (GetRecipes() is { Count: > 0 } recipes)
{
    <div class="row">
        @foreach (var recipe in recipes)
        {
            <div class="col-md-6 mb-3">
                <div class="card">
                    <div class="card-body">
                        <h5 class="card-title">@recipe.Title</h5>
                        <p class="card-text text-muted">@recipe.Summary</p>
                        <a href="@($"recipe/{recipe.Id}")" class="btn btn-outline-primary btn-sm">View Recipe</a>
                    </div>
                </div>
            </div>
        }
    </div>
}
else
{
    <p class="text-muted">No recipes found in this category yet. <a href="/submit">Submit one!</a></p>
}

@code {
    [Parameter]
    public string Slug { get; set; } = "";

    private string GetCategoryName() => Slug switch
    {
        "breakfast" => "Breakfast",
        "main-courses" => "Main Courses",
        "desserts" => "Desserts",
        "appetizers" => "Appetizers",
        "soups-salads" => "Soups & Salads",
        "vegetarian" => "Vegetarian",
        _ => "Unknown Category"
    };

    private List<RecipeInfo> GetRecipes() => RecipeData.GetByCategory(Slug);

    private record RecipeInfo(int Id, string Title, string Summary);
}

@page "/recipe/{Id:int}"

<PageTitle>@GetRecipe()?.Title - RecipeShare</PageTitle>

@if (GetRecipe() is { } recipe)
{
    <h1>@recipe.Title</h1>
    <p class="text-muted">Category: <a href="@($"category/{recipe.Category}")">@recipe.CategoryName</a></p>

    <h3>Ingredients</h3>
    <ul>
        @foreach (var ingredient in recipe.Ingredients)
        {
            <li>@ingredient</li>
        }
    </ul>

    <h3>Steps</h3>
    <ol>
        @foreach (var step in recipe.Steps)
        {
            <li class="mb-2">@step</li>
        }
    </ol>

    <hr />
    <h4>Rate this Recipe</h4>
    <StarRating RecipeId="Id" />
}
else
{
    <h1>Recipe Not Found</h1>
    <p>Sorry, we couldn't find that recipe. <a href="/">Browse categories</a></p>
}

@code {
    [Parameter]
    public int Id { get; set; }

    private RecipeDetail? GetRecipe() => RecipeData.GetById(Id);
}

@rendermode InteractiveServer

<div class="star-rating" aria-label="Rate this recipe">
    @for (int i = 1; i <= 5; i++)
    {
        var star = i;
        <span class="star @(star <= CurrentRating ? "filled" : "")"
              @onclick="() => SetRating(star)"
              role="button"
              aria-label="@star stars">
            @(star <= CurrentRating ? "★" : "☆")
        </span>
    }
    @if (CurrentRating > 0)
    {
        <span class="ms-2 text-muted">You rated this @CurrentRating/5</span>
    }
</div>

@code {
    [Parameter]
    public int RecipeId { get; set; }

    private int CurrentRating { get; set; }

    private void SetRating(int rating)
    {
        CurrentRating = rating;
    }
}

.star-rating {
    font-size: 1.8rem;
    display: inline-flex;
    align-items: center;
    gap: 0.1rem;
}

.star {
    cursor: pointer;
    color: #ccc;
    transition: color 0.15s;
}

.star:hover,
.star.filled {
    color: #f5a623;
}

using System.ComponentModel.DataAnnotations;

namespace RecipeShare;

public class RecipeFormModel
{
    [Required(ErrorMessage = "Please enter a recipe title.")]
    [StringLength(100, MinimumLength = 3, ErrorMessage = "Title must be between 3 and 100 characters.")]
    public string Title { get; set; } = "";

    [Required(ErrorMessage = "Please select a category.")]
    public string Category { get; set; } = "";

    [Required(ErrorMessage = "Please list the ingredients.")]
    public string Ingredients { get; set; } = "";

    [Required(ErrorMessage = "Please describe the steps.")]
    public string Steps { get; set; } = "";
}

