@page "/category/{Slug}"

<PageTitle>@GetCategoryName() - RecipeShare</PageTitle>

<h1>@GetCategoryName()</h1>
<p><a href="/">← Back to Categories</a></p>

@if (GetRecipes() is { Count: > 0 } recipes)
{
    <div class="row">
        @foreach (var recipe in recipes)
        {
            <div class="col-md-6 mb-3">
                <div class="card">
                    <div class="card-body">
                        <h5 class="card-title">@recipe.Title</h5>
                        <p class="card-text text-muted">@recipe.Summary</p>
                        <a href="@($"recipe/{recipe.Id}")" class="btn btn-outline-primary btn-sm">View Recipe</a>
                    </div>
                </div>
            </div>
        }
    </div>
}
else
{
    <p class="text-muted">No recipes found in this category yet. <a href="/submit">Submit one!</a></p>
}

@code {
    [Parameter]
    public string Slug { get; set; } = "";

    private string GetCategoryName() => Slug switch
    {
        "breakfast" => "Breakfast",
        "main-courses" => "Main Courses",
        "desserts" => "Desserts",
        "appetizers" => "Appetizers",
        "soups-salads" => "Soups & Salads",
        "vegetarian" => "Vegetarian",
        _ => "Unknown Category"
    };

    private List<RecipeInfo> GetRecipes() => RecipeData.GetByCategory(Slug);

    private record RecipeInfo(int Id, string Title, string Summary);
}

